// Dynamically generate remaining devices so all 30 devices have realistic human names
export const INITIAL_DEVICES: DeviceRecord[] = Array.from({ length: 30 }, (_, idx) => {
  const num = idx + 1;
  const id = `DEV-${String(num).padStart(3, '0')}`;
  const existing = BASE_DEVICES.find((d) => d.id === id);
  if (existing) return existing;

  const citizenName = BACKGROUND_CITIZEN_NAMES[idx] || `Resident ${num}`;
  const isDelivery = num % 5 === 0;
  const isStaticResident = num % 3 === 0;
  const baseMinute = 1085 + (num * 3) % 75;
  const hh = Math.floor(baseMinute / 60);
  const mm = String(baseMinute % 60).padStart(2, '0');
  const timeStr = `${hh}:${mm}`;
  const sectorId = num % 2 === 0 ? 'BLR-KVR-04A' : 'BLR-KVR-04B';

  return {
    id,
    label: `${citizenName}’s Phone (${isDelivery ? 'Delivery Partner' : isStaticResident ? 'Indiranagar 100Ft Road Resident' : 'Evening Commuter'})`,
    category: isDelivery ? 'Service / Delivery Device' : 'Resident / Commuter Device',
    ownerNote: isStaticResident
      ? `${citizenName} — Indiranagar 100Ft Road Apartment Resident (Stationary Sector Registration)`
      : `${citizenName} — Routine Evening Commuter along 80ft Link Road`,
    imeiMask: `3577${String(num).padStart(2, '0')}-XX-SYN-00${String(num).padStart(2, '0')}`,
    firstObserved: '18:00',
    lastObserved: '19:45',
    sectorIds: [sectorId],
    observationsCount: 2 + (num % 4),
    relevanceStatus: 'Routine Background Traffic',
    confidenceNote: isStaticResident
      ? `Zero sector handovers for ${citizenName} during incident window; consistent with stationary apartment resident.`
      : `Single-sector transient pass by ${citizenName} along main road; no multi-point correlation with Aarav Sharma.`,
    limitations:
      'Macro cell-sector covers hundreds of apartments and arterial road lanes. Presence in tower dump is expected for thousands of innocent citizens.',
    alternativeExplanation: isStaticResident
      ? `${citizenName} remained inside their residence within Sector coverage footprint.`
      : `${citizenName} commuting through normal evening traffic on 80ft Link Road.`,
    observations: [
      {
        obsId: `OBS-${id}-1`,
        deviceId: id,
        timestamp: timeStr,
        timeMinutes: baseMinute,
        cellSectorId: sectorId,
        cellSectorName:
          sectorId === 'BLR-KVR-04A'
            ? 'Indiranagar 100Ft Road West Micro-Sector 04A'
            : 'Indiranagar 100Ft Road East Sector 04B',
        approxCoordinates:
          sectorId === 'BLR-KVR-04A'
            ? [12.9675 + (num % 5) * 0.0004, 77.6401 + (num % 4) * 0.0005]
            : [12.9691 + (num % 5) * 0.0004, 77.6451 + (num % 4) * 0.0005],
        sectorRadiusMeters: sectorId === 'BLR-KVR-04A' ? 450 : 650,
        azimuthDeg: sectorId === 'BLR-KVR-04A' ? 85 : 110,
        eventType: num % 2 === 0 ? 'Periodic Network Registration' : 'Packet Data Session',
        sourceRecordRef: 'EVD-003 (Tower-Dump-Routine)',
        authorisationRef: 'AUTH-BLR-SYN-2026-8841',
        signalQuality: 'Medium (Macro Sector)',
        isRelevantWindow: baseMinute >= 1110 && baseMinute <= 1145,
        notes: `Filtered as routine background cell traffic for ${citizenName} (no multi-sector corridor correlation).`,
      },
    ],
  };
});

